use std::sync::atomic::{AtomicBool, Ordering}; use std::thread; use std::time::Duration; static IS_LOCKED: AtomicBool = AtomicBool::new(false); static HOOK_THREAD_ID: std::sync::atomic::AtomicU32 = std::sync::atomic::AtomicU32::new(0); static LOCK_MUTEX: std::sync::Mutex<()> = std::sync::Mutex::new(()); pub fn lock_hardware_input() { let _guard = LOCK_MUTEX.lock().unwrap(); if IS_LOCKED.swap(true, Ordering::Relaxed) { return; } let (tx, rx) = std::sync::mpsc::channel(); thread::spawn(move || { HOOK_THREAD_ID.store(1234, Ordering::Relaxed); let _ = tx.send(()); loop { thread::sleep(Duration::from_millis(100)); } }); let _ = rx.recv(); } pub fn unlock_hardware_input() { let _guard = LOCK_MUTEX.lock().unwrap(); if !IS_LOCKED.swap(false, Ordering::Relaxed) { return; } let tid = HOOK_THREAD_ID.swap(0, Ordering::Relaxed); println!("Unlocked, tid was {}", tid); } fn main() { lock_hardware_input(); unlock_hardware_input(); lock_hardware_input(); unlock_hardware_input(); }
